// PATCH D: cache LRU com TTL 5min (300000ms) + cap 50 entradas; não invalida em page:change
const _listCache=new Map();const LIST_TTL=5*60*1000;const LIST_MAX=50;
function _listCacheGet(k){const e=_listCache.get(k);if(!e)return null;if(Date.now()-e.at>LIST_TTL){_listCache.delete(k);return null;}_listCache.delete(k);_listCache.set(k,e);return e.files;}
