// PATCH I: MutationObserver no lugar do polling de 40×250ms (one-shot, desconecta após 10s)
function gdiAnnounceVideoFromDOM(){
  const wrap=document.querySelector('.gdi-player-wrap');
  if(!wrap){
    // fallback: player nativo sem wrap — tenta direto
    const v0=document.querySelector('video');
    if(v0)gdiAnnounceMedia('video',v0);
    return;
  }
  const v=wrap.querySelector('video');
  if(v){gdiAnnounceMedia('video',v);return;}
  const obs=new MutationObserver(function(){
    const v2=wrap.querySelector('video');
    if(v2){gdiAnnounceMedia('video',v2);obs.disconnect();}
  });
  obs.observe(wrap,{childList:true,subtree:true});
  setTimeout(function(){obs.disconnect();},10000);
}
gdiAnnounceVideoFromDOM();

